def roles_from_role_field(apps, schema_editor):
    """Membership.role (owner/member) becomes a Membership.roles assignment.

    Users without any organization get a personal one, like new signups.
    """
    Role = apps.get_model("orgs", "Role")
    Membership = apps.get_model("orgs", "Membership")
    Organization = apps.get_model("orgs", "Organization")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    roles = {}
    for name, description, descendant in ROLES:
        roles[name], _ = Role.objects.get_or_create(
            name=name,
            defaults={"description": description, "descendant": roles.get(descendant)},
        )
    for membership in Membership.objects.all():
        membership.roles.add(roles["owner" if membership.role == "owner" else "member"])
    for user in User.objects.filter(is_active=True, memberships__isnull=True):
        org = Organization.objects.create(
            name=f"{user.username or user.email}'s workspace"[:100]
        )
        Membership.objects.create(organization=org, user=user).roles.add(roles["owner"])


def role_field_from_roles(apps, schema_editor):
    """Reverse: owner-role holders get role="owner" back; everyone else, admins included, "member".

    Personal workspaces made on the way forward are kept: deleting them could
    destroy data created since.
    """
    Membership = apps.get_model("orgs", "Membership")
    Membership.objects.filter(roles__name="owner").update(role="owner")


